ALTER TABLE public.workspaces ADD COLUMN appearance jsonb NOT NULL DEFAULT '{"preset":"enterprise","accent":"emerald","wallpaper":null}'::jsonb;
CREATE OR REPLACE FUNCTION public.guard_workspace_appearance() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.appearance IS DISTINCT FROM OLD.appearance AND auth.role() <> 'service_role' THEN IF COALESCE(public.workspace_role(OLD.id),'') NOT IN ('admin','office_admin') OR NOT public.workspace_writable(OLD.id) THEN RAISE EXCEPTION 'Workspace appearance is manager-controlled and requires a writable workspace'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_workspace_appearance BEFORE UPDATE ON public.workspaces FOR EACH ROW EXECUTE FUNCTION public.guard_workspace_appearance();
CREATE OR REPLACE FUNCTION public.wallpaper_workspace_id(_path text) RETURNS bigint LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT CASE WHEN split_part(_path,'/',1) ~ '^[1-9][0-9]{0,12}$' THEN split_part(_path,'/',1)::bigint ELSE NULL END $$;
GRANT EXECUTE ON FUNCTION public.wallpaper_workspace_id(text) TO authenticated;
CREATE POLICY "Workspace members read wallpapers" ON storage.objects FOR SELECT TO authenticated USING (bucket_id='workspace-wallpapers' AND public.workspace_role(public.wallpaper_workspace_id(name)) IS NOT NULL);
CREATE POLICY "Workspace managers upload wallpapers" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id='workspace-wallpapers' AND public.workspace_role(public.wallpaper_workspace_id(name)) IN ('admin','office_admin') AND public.workspace_writable(public.wallpaper_workspace_id(name)) AND lower(storage.extension(name)) IN ('jpg','jpeg','png','webp'));
CREATE POLICY "Workspace managers delete wallpapers" ON storage.objects FOR DELETE TO authenticated USING (bucket_id='workspace-wallpapers' AND public.workspace_role(public.wallpaper_workspace_id(name)) IN ('admin','office_admin') AND public.workspace_writable(public.wallpaper_workspace_id(name)));